{
  "claims": [
    {
      "id": "c1",
      "claim": "The sleep() method of urllib3's Retry utility sleeps between retry attempts.",
      "citation": "Sleep between retry attempts.",
      "type": "fact"
    },
    {
      "id": "c2",
      "claim": "The sleep() method of urllib3's Retry utility respects a server’s Retry-After response header.",
      "citation": "This method will respect a server’s `Retry-After` response header",
      "type": "fact"
    },
    {
      "id": "c3",
      "claim": "When a Retry-After header is present, the sleep() method of urllib3's Retry utility sleeps for the duration requested by the header.",
      "citation": "sleep the duration of the time requested",
      "type": "fact"
    },
    {
      "id": "c4",
      "claim": "If a Retry-After header is not present, the sleep() method of urllib3's Retry utility uses an exponential backoff.",
      "citation": "If that is not present, it will use an exponential backoff",
      "type": "fact"
    },
    {
      "id": "c5",
      "claim": "The default backoff factor for the sleep() method of urllib3's Retry utility is 0.",
      "citation": "By default, the backoff factor is 0",
      "type": "fact"
    },
    {
      "id": "c6",
      "claim": "When the backoff factor is 0, the sleep() method of urllib3's Retry utility returns immediately.",
      "citation": "this method will return immediately",
      "type": "fact"
    }
  ]
}

{
  "claims": [
    {
      "id": "c1",
      "claim": "The read_timeout property of urllib3's Timeout class returns the value for the read timeout.",
      "citation": "Get the value for the read timeout.",
      "type": "fact"
    },
    {
      "id": "c2",
      "claim": "The read_timeout property assumes some time has elapsed in the connection timeout.",
      "citation": "This assumes some time has elapsed in the connection timeout",
      "type": "fact"
    },
    {
      "id": "c3",
      "claim": "The read_timeout property computes the read timeout appropriately.",
      "citation": "computes the read timeout appropriately",
      "type": "fact"
    },
    {
      "id": "c4",
      "claim": "If self.total is set, the read timeout is dependent on the amount of time taken by the connect timeout.",
      "citation": "If self.total is set, the read timeout is dependent on the amount of time taken by the connect timeout.",
      "type": "fact"
    },
    {
      "id": "c5",
      "claim": "If the connection time has not been established, a TimeoutStateError will be raised.",
      "citation": "If the connection time has not been established, a `TimeoutStateError` will be raised.",
      "type": "fact"
    },
    {
      "id": "c6",
      "claim": "The read_timeout property raises urllib3.exceptions.TimeoutStateError if start_connect() has not yet been called on the object.",
      "citation": "`urllib3.exceptions.TimeoutStateError` – If `start_connect()` has not yet been called on this object.",
      "type": "fact"
    }
  ]
}

{
  "claims": [
    {
      "id": "c1",
      "claim": "Timeouts in urllib3 control how long requests are allowed to run before being aborted.",
      "citation": "Timeouts allow you to control how long (in seconds) requests are allowed to run before being aborted.",
      "type": "fact"
    },
    {
      "id": "c2",
      "claim": "Timeouts in urllib3 are specified in seconds.",
      "citation": "how long (in seconds) requests are allowed to run",
      "type": "fact"
    },
    {
      "id": "c3",
      "claim": "In simple cases, a timeout can be specified as a float to the request() function.",
      "citation": "In simple cases, you can specify a timeout as a `float` to `request()`",
      "type": "fact"
    },
    {
      "id": "c4",
      "claim": "A Timeout instance allows specifying separate connect and read timeouts.",
      "citation": "a `Timeout` instance which lets you specify separate connect and read timeouts",
      "type": "fact"
    },
    {
      "id": "c5",
      "claim": "A timeout can be specified at the PoolManager level to apply to all requests.",
      "citation": "If you want all requests to be subject to the same timeout, you can specify the timeout at the `PoolManager` level",
      "type": "fact"
    },
    {
      "id": "c6",
      "claim": "A pool-level timeout can be overridden by specifying a timeout to the request() function.",
      "citation": "You still override this pool-level timeout by specifying `timeout` to `request()`",
      "type": "fact"
    }
  ]
}

